const VOICE_DATA = {"file":"voice/ep07.mp3","lines":{"ep07_001":{"who":"TAKUTO","text":"Previously. Forty Red Giants marched on Fort Cinder, in step, like soldiers.","mono":true,"off":0.25,"dur":5.291,"env":"011666425687332123211100000006899766542587742113466554444322114455541220244431003542012224554423221100244322200687410000000243300222254433201111000010000000000"},"ep07_002":{"who":"TAKUTO","text":"I opened the door in the axe. Just a crack. Akuro looked out through my eyes.","mono":true,"off":5.9407,"dur":4.949,"env":"00035522799117454522565655444443223443210023310024444023001157652100000000000000000578500114543676543244100455431001134344333123443211000122100000000"},"ep07_003":{"who":"TAKUTO","text":"Rin got hurt. I did that.","mono":true,"off":11.29,"dur":1.621,"env":"0157877748997212897510014542477221444211000000000"},"ep07_004":{"who":"TAKUTO","text":"And the Guild executioner told me she always comes.","mono":true,"off":13.3113,"dur":3.072,"env":"013545211589862675012220001442222332221011145542343323122123554333332201135421000011000000000"},"ep07_005":{"who":"OGRE","text":"Run. Run, little ones. Do not look back.","mono":false,"off":16.7833,"dur":3.051,"env":"01496886743322100000013599765432222566544333322222321000000003454555652146410025554321000000"},"ep07_006":{"who":"OGRE","text":"The grey is in the trees.","mono":false,"off":20.234,"dur":1.856,"env":"01682002356799865311000146645544343112224444422110011000"},"ep07_007":{"who":"OGRE","text":"The grey that walks like a man.","mono":false,"off":22.49,"dur":2.005,"env":"0058310133466577633210343111247964133345313433456544211000000"},"ep07_008":{"who":"RIN","text":"I am walking. I am not riding in that cart for one more hour.","mono":false,"off":24.8953,"dur":3.456,"env":"03567778876996002354431000046777787765412126667744555554542001135443102214422555555444443333222100000000"},"ep07_009":{"who":"SIEG","text":"The medic said ten days.","mono":false,"off":28.7513,"dur":1.771,"env":"079987674575212322687553001239766676577665444332210000"},"ep07_010":{"who":"RIN","text":"The medic said a lot of things. He also said Wick was a lamp.","mono":false,"off":30.922,"dur":3.392,"env":"047998874850123368567667775441004654444321210000046468773335663332764222672000443464444433210000000000"},"ep07_011":{"who":"WICK","text":"He did! He tried to hang a pot over me!","mono":false,"off":34.714,"dur":2.005,"env":"0065259988222135222498633545654530115774555214332211110000000"},"ep07_012":{"who":"SIEG","text":"Two days, Nemu. You called it.","mono":false,"off":37.1193,"dur":2.283,"env":"149976567655566665432038876667776665554100000188315986675564311210000"},"ep07_013":{"who":"NEMU","text":"I always call it. I just never say it loud enough.","mono":false,"off":39.802,"dur":3.541,"env":"01230189864753331211433211001000000000000000000003750536342001678830554432555333100255555424333211000000000"},"ep07_014":{"who":"RIN","text":"...Why is he walking so far behind?","mono":false,"off":43.7433,"dur":2.027,"env":"0247999998845376469930146643458731157761642245544332211000000"},"ep07_015":{"who":"NEMU","text":"He's been walking behind since the fort. Ten steps. Always ten.","mono":false,"off":46.17,"dur":4.971,"env":"002541397765567720245653343113555544322112254320141113333210001000000000000000022797643230453210013221000000000000000000499975565432211313543211000000"},"ep07_016":{"who":"RIN","text":"Takuto! Walk with us!","mono":false,"off":51.5407,"dur":1.451,"env":"02797216952379998644698401275354312332000000"},"ep07_017":{"who":"TAKUTO","text":"I'm fine here.","mono":false,"off":53.3913,"dur":1.024,"env":"1456521159666554213332110000000"},"ep07_018":{"who":"RIN","text":"You are ten steps away so you can swing the axe without hitting anybody. I know what you are doing.","mono":false,"off":54.8153,"dur":5.525,"env":"0267998401315778533157302336536766654333255444112663443127678756413555410122052466421145455411456641444332222110000000000015677777775357302234554213543322211000000000"},"ep07_019":{"who":"TAKUTO","text":"...Eleven, then.","mono":false,"off":60.7407,"dur":1.003,"env":"0255689923555315654311100000000"},"ep07_020":{"who":"RIN","text":"Idiot.","mono":false,"off":62.1433,"dur":0.661,"env":"07947889973012100000"},"ep07_021":{"who":"NEMU","text":"I'll walk with him. Ten steps behind is a good place for a nap anyway.","mono":false,"off":63.2047,"dur":5.397,"env":"022553224565310113301211100000000000000000000000000000214988753230364103301441125454433211100000000005546503498100210554211222310024555545544310121765432211100000"},"ep07_022":{"who":"SIEG","text":"Nemu. Wait. Look at the road.","mono":false,"off":69.002,"dur":2.176,"env":"079776677666666644577766664243200000389625620677777765544332200000"},"ep07_023":{"who":"WICK","text":"Feathers? Big ones. Red and black.","mono":false,"off":71.578,"dur":1.813,"env":"0059946887420099523576556431268774666514565421000000000"},"ep07_024":{"who":"SIEG","text":"Plume Ogres. The same feathers we found at Marrowmere.","mono":false,"off":73.7913,"dur":3.477,"env":"017976664102666643665443321000000000047533576555554103654455554320476203755555464103775555555443322110000"},"ep07_025":{"who":"RIN","text":"Plume Ogres live deep in the Greatwood. They never come out to the roads.","mono":false,"off":77.6687,"dur":4.032,"env":"0038888962479941467653414665666200035442014455411266642000333211000000016777775154011355555542013214325544332210133200000"},"ep07_026":{"who":"SIEG","text":"Never is a word that keeps getting broken lately.","mono":false,"off":82.1007,"dur":3.093,"env":"199864665214765776666665666544320000000037411339641242067577765387666214776677774102443210000"},"ep07_027":{"who":"NEMU","text":"Can I tell you what dying feels like?","mono":false,"off":85.594,"dur":2.432,"env":"0217899980162388973321000000000028300069989998766411146764365222221001000"},"ep07_028":{"who":"TAKUTO","text":"...You want to?","mono":false,"off":88.426,"dur":0.981,"env":"002553599853044565321110000000"},"ep07_029":{"who":"NEMU","text":"Nobody ever asks. So I want to.","mono":false,"off":89.8073,"dur":2.816,"env":"0028997239645300489314430355321102220122210000000000000133656776435565100341321000000"},"ep07_030":{"who":"NEMU","text":"First it is cold. Like falling into the river in winter. Then it is warm, like a blanket. Then nothing for a while.","mono":false,"off":93.0233,"dur":9.131,"env":"0001676334413132344330211255431000000200000000000000000014302111566676676566441015314872123323544435531241101000000000000000000000000000000000017999775320003852155430012466666554332100000002540241043454302110001100000000000000000002776555663101423220111334431333332111100000"},"ep07_031":{"who":"NEMU","text":"Then you wake up, and you are very, very hungry. And everyone around you is crying.","mono":false,"off":102.554,"dur":6.144,"env":"01257886136663003343210001000000000000000277557643454111165543221100000000001664444211345431011000000000000000000000000000000036420399114762574554355555544323210154301133332210000000000"},"ep07_032":{"who":"TAKUTO","text":"That is why you sleep so much.","mono":false,"off":109.098,"dur":1.749,"env":"00479894337999765533214543012338655444321000110000000"},"ep07_033":{"who":"NEMU","text":"Sleeping is the warm part, without the cold part first. It is cheating.","mono":false,"off":111.2473,"dur":5.525,"env":"0123229972038755432653016533679998662222422210020000000000000581787403520415776551102235531111115542110023230200000000000000000000000000049365352145435776522311000000"},"ep07_034":{"who":"TAKUTO","text":"...At the fort. You shouted my name. I heard it from very far away.","mono":false,"off":117.1727,"dur":4.203,"env":"0005610152111158897420001223653655543421343333334332110000000000001444212677355011334312444332110344433333223332110000000000000"},"ep07_035":{"who":"NEMU","text":"I am very loud when I want to be. I just almost never want to.","mono":false,"off":121.7753,"dur":4.715,"env":"0225666641157655555223454432110001000344445303331003102211000000000000000000000000000125334445130598776524302102577710552344431000331220000000"},"ep07_036":{"who":"NEMU","text":"If you go red again, I will shout again. Every time. Even if you are a hundred steps behind.","mono":false,"off":126.89,"dur":7.445,"env":"02211275038876326664440234333322100000000000000367621212444355543223022210000000000000000000000000000000000003893125511411554431110000000000000000000499941697774111267542266544421116776224302334035310433024411343321000020000"},"ep07_037":{"who":"TAKUTO","text":"And if I don't hear you?","mono":false,"off":134.7353,"dur":1.301,"env":"0457621987359631111455443232211010000000"},"ep07_038":{"who":"NEMU","text":"Then I will bite you.","mono":false,"off":136.4367,"dur":1.408,"env":"0179986643100047762343035554300442110000000"},"ep07_039":{"who":"TAKUTO","text":"...Fair.","mono":false,"off":138.2447,"dur":0.683,"env":"022111897764322100000"},"ep07_040":{"who":"CROWD","text":"Hunters! On the road! Hunters!","mono":false,"off":139.3273,"dur":2.176,"env":"004998406887632117666654357987542221100014655202211111221000000000"},"ep07_041":{"who":"CROWD2","text":"Finally. Somebody fetch the elder.","mono":false,"off":141.9033,"dur":2.176,"env":"000997666665444432121266433763530047512210333455431332211000000000"},"ep07_042":{"who":"HUNTER","text":"Welcome, Hunters. I am Abel, elder of this ford. You came about the ogres?","mono":false,"off":144.4793,"dur":4.736,"env":"00479960037553246541123332110023333331123442123321002444312332100221110002332322100000001100144333114320022223332101111100000000000000000000000"},"ep07_043":{"who":"HUNTER","text":"Three raids in four nights. They take grain. Only grain. And they burned the mill.","mono":false,"off":149.6153,"dur":4.757,"env":"00015664369976412233200145433344332001101201143100003543322211110000233333210014433222111100000012222100344332211222222111000000000000000000000"},"ep07_044":{"who":"SIEG","text":"Anyone hurt?","mono":false,"off":154.7727,"dur":1.109,"env":"0687777656656677459777643223210000"},"ep07_045":{"who":"HUNTER","text":"Old Merrick broke his leg running. And the Pell boy was knocked into the river. No one dead. Yet.","mono":false,"off":156.282,"dur":5.611,"env":"0378854799999830001887201432224664212344433222210000013442022687742167788654223222555553100023211022234410121100000000345554444442156544310000013321000000000000000000000"},"ep07_046":{"who":"CROWD2","text":"Yet!","mono":false,"off":162.2927,"dur":0.683,"env":"013499878764111000000"},"ep07_047":{"who":"WICK","text":"Everybody keeps saying yet. I really hate yet.","mono":false,"off":163.3753,"dur":2.517,"env":"0552685288975621145134436555555554443000002665346555431365410233321001000000"},"ep07_048":{"who":"NEMU","text":"Yet is just tomorrow being rude.","mono":false,"off":166.2927,"dur":2.005,"env":"0058621019542053652420100327887765443203555544455531000020000"},"ep07_049":{"who":"RIN","text":"Plume Ogres eat meat. Why would they steal grain?","mono":false,"off":168.698,"dur":2.795,"env":"003998974489931676331144200455432012100002478777466127633432455431136644332221000000"},"ep07_050":{"who":"SIEG","text":"Because whatever they are running from does not let them hunt.","mono":false,"off":171.8927,"dur":3.605,"env":"0752496544555431146544554433555545555455444455443211464344300000000675447644310056641000455542116542110121000"},"ep07_051":{"who":"TAKUTO","text":"Running from what?","mono":false,"off":175.898,"dur":1.109,"env":"0138998976322766568996310022000000"},"ep07_052":{"who":"SIEG","text":"That's the question. And the village wants an answer with a sword in it.","mono":false,"off":177.4073,"dur":3.989,"env":"198513304731297652023765542000000000079987778656665554677655532575214676543247666410003765764332276667654665443210110000"},"ep07_053":{"who":"HUNTER","text":"Kill them, Hunters. Whatever the Guild charges. Before they come back.","mono":false,"off":181.7967,"dur":4.203,"env":"0029995387654466540144432101245347842442421145543100221466554310012211000000012001442332001133222234332100000000000000000000000"},"ep07_054":{"who":"SIEG","text":"We will stand watch tonight. And then we will see.","mono":false,"off":186.3993,"dur":2.944,"env":"29777643207766565666655553133112887766554211000000000699886655667655655332247654332210000"},"ep07_055":{"who":"WICK","text":"Real flour. Real wheat flour. Fresh eggs. Cabbage. Takuto. TAKUTO.","mono":false,"off":189.7433,"dur":4.245,"env":"04799987311378776776544888887645874001266654333310016874326655422243200011787536632310358630175144654311345301156543321100000000"},"ep07_056":{"who":"TAKUTO","text":"You can make it.","mono":false,"off":194.3887,"dur":1.067,"env":"01364139776788763013532000000000"},"ep07_057":{"who":"WICK","text":"I can make it! Okonomiyaki! Proper! Almost proper! No sauce, but almost!","mono":false,"off":195.8553,"dur":4.224,"env":"0462197778773019860004873028676666666555530112121000157630066530157766764101476510455556554444365543420254544432211132010000000"},"ep07_058":{"who":"WICK","text":"Will-o'-Wisp, very gently. Only the pan. Only the PAN.","mono":false,"off":200.4793,"dur":3.349,"env":"03765998769755001387665433447631123331000377666666252125554433200005655655532411235554332221100000000"},"ep07_059":{"who":"WICK","text":"And... flip!","mono":false,"off":204.2287,"dur":0.832,"env":"0478878731248975102221000"},"ep07_060":{"who":"NEMU","text":"It is a pancake with cabbage in it.","mono":false,"off":205.4607,"dur":2.304,"env":"0294996452032399984211321100010000000018512022367823723534433210010000"},"ep07_061":{"who":"WICK","text":"It is my mother's pancake with cabbage in it. Eat it with respect.","mono":false,"off":208.1647,"dur":3.349,"env":"05688647797776995677420257665116763003621012789647422544321000000003687377423521353430075320001000000"},"ep07_062":{"who":"NEMU","text":"...Mm. Oh. Oh no. It's good.","mono":false,"off":211.914,"dur":2.069,"env":"016776655320000000079863100007988766654321001035304421111120000"},"ep07_063":{"who":"SIEG","text":"It IS good. Wick. Why have you been feeding us burned rabbit for a month?","mono":false,"off":214.3833,"dur":4.181,"env":"088887663116766665453000000698752001100000000006767876776556664111766566655644201187665554456655546411113877666665432111110000"},"ep07_064":{"who":"WICK","text":"Because nobody gave me flour!","mono":false,"off":218.9647,"dur":1.835,"env":"04216975468787783287364215656314542111576653321110000000"},"ep07_065":{"who":"TAKUTO","text":"...It tastes like Osaka.","mono":false,"off":221.1993,"dur":1.728,"env":"0057202379874321575313565533265542014653210000000000"},"ep07_066":{"who":"WICK","text":"You've never been to Osaka.","mono":false,"off":223.3273,"dur":1.749,"env":"04863789973895378774427314776444377641115643221000000"},"ep07_067":{"who":"TAKUTO","text":"It tastes like what I thought Osaka would taste like.","mono":false,"off":225.4767,"dur":3.179,"env":"042032899874422213655420035566652006875100577643335555411145554333102145442210122110000000000000"},"ep07_068":{"who":"WICK","text":"...That's the nicest thing anyone's said to me in three years. Shut up. Eat.","mono":false,"off":229.0553,"dur":3.669,"env":"039942305877887633654201866533678766766433286322566555520126776445543321221000001229967861000045532101000000000"},"ep07_069":{"who":"RIN","text":"Takuto. Pass the salt.","mono":false,"off":233.1247,"dur":1.536,"env":"03798317942799997302566533044334655432001000000"},"ep07_070":{"who":"RIN","text":"It's salt. Not my arm. You won't break it.","mono":false,"off":235.0607,"dur":2.261,"env":"03055489987222288863367773566655555424664798630048663013421022000000"},"ep07_071":{"who":"TAKUTO","text":"I'm sorry. About the fort. I keep thinking about it.","mono":false,"off":237.722,"dur":3.136,"env":"00367745558999987555552776103211178875210000000000147401135410005652144553255433222100000000000"},"ep07_072":{"who":"RIN","text":"Stop. I heard you the first time. And the second. And the ninth. Say it again and I'll tie your mouth shut.","mono":false,"off":241.258,"dur":5.909,"env":"0121498776300105664258994256354111786333021444444444200257663443752014444210004677777776553100000000000002338888778586215865555432555551121245555445454443212332443100010000000000"},"ep07_073":{"who":"TAKUTO","text":"Can you do that?","mono":false,"off":247.5673,"dur":1.003,"env":"0178777742599839986421000000000"},"ep07_074":{"who":"RIN","text":"Do you want to find out?","mono":false,"off":248.97,"dur":1.323,"env":"0367986899523311277677566544321022100000"},"ep07_075":{"who":"TAKUTO","text":"...Here is the salt.","mono":false,"off":250.6927,"dur":1.088,"env":"002378899621463325997421000000000"},"ep07_076":{"who":"RIN","text":"Thank you.","mono":false,"off":252.1807,"dur":0.747,"env":"03999942269876532100000"},"ep07_077":{"who":"CROWD","text":"OGRES! The granary! OGRES!","mono":false,"off":253.3273,"dur":2.219,"env":"1799996359887440053115788875432221110000466664212211112222100000000"},"ep07_078":{"who":"CROWD2","text":"They are taking the sacks!","mono":false,"off":255.946,"dur":1.579,"env":"024999996123777314554532115987753101111000000000"},"ep07_079":{"who":"CROWD","text":"The barn is on fire!","mono":false,"off":257.9247,"dur":1.835,"env":"04521298788765444223334333331000044443321111000000000000"},"ep07_080":{"who":"SIEG","text":"That's the chieftain. The one with the mask. Takuto, careful.","mono":false,"off":260.1593,"dur":3.84,"env":"08741430485145397762017766664000000898866666665466777655554433410000000000019975219975228766665212987641145432210000"},"ep07_081":{"who":"AKURO","text":"A big one. Feathers and bone. Let me look, boy.","mono":true,"off":264.3993,"dur":3.179,"env":"017842399985423467756422111489757999655778642689877654322100002586468876641001578776432211000000"},"ep07_082":{"who":"TAKUTO","text":"No.","mono":false,"off":267.978,"dur":0.619,"env":"0145899876432000000"},"ep07_083":{"who":"RIN","text":"Spear! Low!","mono":false,"off":268.9967,"dur":0.917,"env":"0132078987667877654332000000"},"ep07_084":{"who":"TAKUTO","text":"Break!","mono":false,"off":270.314,"dur":0.64,"env":"00489976520011100000"},"ep07_085":{"who":"NEMU","text":"He broke its spear!","mono":false,"off":271.354,"dur":1.195,"env":"000892489994036203334203754322110000"},"ep07_086":{"who":"RIN","text":"One arm is enough for this! Red Thread!","mono":false,"off":272.9487,"dur":2.283,"env":"026999854888899646777752111174165422332100023798720011376433201000000"},"ep07_087":{"who":"SIEG","text":"Afterimage! Finish it, Takuto!","mono":false,"off":275.6313,"dur":2.347,"env":"05876212898778776664310000006987874377532000289762199863298754333321000"},"ep07_088":{"who":"OGRE","text":"Not you. Not fighting you.","mono":false,"off":278.378,"dur":2.197,"env":"035596853111235696652110000000012577441111268778777554443444320000"},"ep07_089":{"who":"OGRE","text":"Grain. For the little ones. Hungry. We run from the grey.","mono":false,"off":280.9753,"dur":3.968,"env":"001466787655443311000015644564556565522221101122210000000001469787433432211000001254532378865522343334201457787642100000"},"ep07_090":{"who":"TAKUTO","text":"...It talked.","mono":false,"off":285.3433,"dur":0.896,"env":"003672023579986420001000000"},"ep07_091":{"who":"SIEG","text":"Fiends do not talk.","mono":false,"off":286.6393,"dur":1.771,"env":"004977666665545455487766666653110000288654320011000000"},"ep07_092":{"who":"NEMU","text":"That one did.","mono":false,"off":288.81,"dur":1.067,"env":"02786510598754576432202000000000"},"ep07_093":{"who":"OGRE","text":"Kill me, white one. Then they starve slower. Or let me go. Then they starve faster. You choose.","mono":false,"off":290.2767,"dur":6.549,"env":"01249755356544321124576321012222110000000000146665444332124576654212221245577663434311257976545422332124678753211000000000000000024666444433235554552100245554221101110000012222012233553432111110000"},"ep07_094":{"who":"AKURO","text":"Well? It is asking you, boy. Break it, or do not. I am curious too.","mono":true,"off":297.226,"dur":4.8,"env":"013589665422667755433677653422456555687632588787653221100003799873145663013885237997657767542100001345445554431122477755555433321333575332100000"},"ep07_095":{"who":"TAKUTO","text":"...Go.","mono":false,"off":302.426,"dur":0.747,"env":"00222599988653211000000"},"ep07_096":{"who":"RIN","text":"Takuto!","mono":false,"off":303.5727,"dur":0.939,"env":"01789840199534798765432100000"},"ep07_097":{"who":"TAKUTO","text":"Take one sack. Only one. And do not come back to this village.","mono":false,"off":304.9113,"dur":3.84,"env":"02199611037887645449876430010007787667554454321110000000036557667788410247554267664100232343410465322100122100000000"},"ep07_098":{"who":"OGRE","text":"White one. Remember. The grey is coming. For all of us.","mono":false,"off":309.1513,"dur":3.904,"env":"0137899311236676543221001269756887633432110000000000000001573112478796557864311247756433211002354256878677366433331100"},"ep07_099":{"who":"HUNTER","text":"You let it go. You had it on its knees, and you let it go!","mono":false,"off":313.4553,"dur":3.584,"env":"001455996620059887653210002332379545335433301213444433222111100132232233312000133332211000000000000000000000"},"ep07_100":{"who":"CROWD2","text":"Half the barn is ash!","mono":false,"off":317.4393,"dur":1.6,"env":"023799711089339866655444422466555431111110000000"},"ep07_101":{"who":"CROWD","text":"What kind of Hunter lets a Fiend walk away?","mono":false,"off":319.4393,"dur":2.667,"env":"01599101168766211376621232122344205330000025555554223454100333443211000000000000"},"ep07_102":{"who":"TAKUTO","text":"The kind who heard it talk.","mono":false,"off":322.506,"dur":1.451,"env":"00512379988865665347966402648874110000000000"},"ep07_103":{"who":"HUNTER","text":"Fiends do not talk, boy!","mono":false,"off":324.3567,"dur":2.347,"env":"00007989998532359878888620002488876410011146556554322100000000000000000"},"ep07_104":{"who":"NEMU","text":"Everyone keeps saying that. Like if they say it enough, it will be true.","mono":false,"off":327.1033,"dur":5.035,"env":"03971399757876642215500533326776554432433211001100000000000000000000000000286039111188644332788776276665422201110000000000019503620542053217763100000000"},"ep07_105":{"who":"RIN","text":"...My brother died to a Fiend, Takuto.","mono":false,"off":332.538,"dur":2.197,"env":"026788419839941676677221562111466655532013553012640414433211000000"},"ep07_106":{"who":"TAKUTO","text":"I know.","mono":false,"off":335.1353,"dur":0.747,"env":"03677778999854210000000"},"ep07_107":{"who":"RIN","text":"If that ogre had said please before it killed him, would that make it better?","mono":false,"off":336.282,"dur":4.011,"env":"0341117664104789623676533531443556210010555555330042113666300111565531134333320000000378310665412455411410034332221110000"},"ep07_108":{"who":"TAKUTO","text":"No. But it didn't kill anyone here. It took grain. It was starving.","mono":false,"off":340.6927,"dur":3.797,"env":"003689998721886512753531116755545544333203332210000000000720549300023777765544432023134653166777641111000000000000"},"ep07_109":{"who":"SIEG","text":"Rin. He's not wrong. And you're not wrong. That's the worst kind of problem.","mono":false,"off":344.89,"dur":4.416,"env":"0698766554444328764776542015776655555542000000049888776544300367655554333200000000000874243038766755554201476655200286554234322210000"},"ep07_110":{"who":"WICK","text":"Can I say something? Three years ago, a farmer chased me out of his barn with a pitchfork. Because my head was on fire.","mono":false,"off":349.706,"dur":6.464,"env":"01878877454398664447865204765531000148865569986457328766553253100399877776114428765410576567653365311187676655551420227503310244220000000000000522954498666546884346546665520048764322111000000000"},"ep07_111":{"who":"WICK","text":"He thought I was a Fiend. I was just cold and hungry. Like that ogre.","mono":false,"off":356.57,"dur":3.413,"env":"0361088958666546411025555555521026655413544002167666425543156564233211100254100665212454212211100000000"},"ep07_112":{"who":"SIEG","text":"...What do you want to do, Takuto?","mono":false,"off":360.3833,"dur":2.155,"env":"07974466666566543276558776666530000037977511299753378654333210000"},"ep07_113":{"who":"TAKUTO","text":"Find their camp. Find out what the grey is. If they are being pushed, something is pushing them.","mono":false,"off":362.938,"dur":5.611,"env":"0007998787598401117776531000000001988766689873243014211466665544443211122100000000017421188878886325665554111398534420034436654004444433300113635424332221110000000000000"},"ep07_114":{"who":"SIEG","text":"Static.","mono":false,"off":368.9487,"dur":0.747,"env":"02322987779753234221000"},"ep07_115":{"who":"TAKUTO","text":"Static.","mono":false,"off":370.0953,"dur":0.747,"env":"01210999876552000000000"},"ep07_116":{"who":"SIEG","text":"Fine. I'll stay and keep the village from hanging us. Nemu and Wick, go with him. Rin...","mono":false,"off":371.242,"dur":5.333,"env":"0069765565542026765443047665556632373026658656654331276653575566544333333332000000003897777766655545666566530000000077665566621764443200000000000389876533221000"},"ep07_117":{"who":"RIN","text":"I'm going too. Someone has to tie him down if he starts laughing.","mono":false,"off":376.9753,"dur":3.456,"env":"03566762398876665022165433200001235756654345320121112455444442454333333200132221344310222333220012110000"},"ep07_118":{"who":"WICK","text":"This forest is very big and very quiet, and I would like to state for the record that I hate it.","mono":false,"off":380.8313,"dur":4.843,"env":"04965410199999843146654338877885317887732446742777764011499753321010000000478876735985124554128763001564754587401454325355443226554221000000000000"},"ep07_119":{"who":"NEMU","text":"Forests are quiet when something big is listening.","mono":false,"off":386.074,"dur":3.563,"env":"00017899976523310424410121056654211000100000000000000003984437640498851498764310200005643046443222211100000"},"ep07_120":{"who":"WICK","text":"Why would you say that?! Why would you say that out loud?!","mono":false,"off":390.0367,"dur":2.539,"env":"04999895477554888983787751002599888547655378775485677641246664332211000000000"},"ep07_121":{"who":"RIN","text":"Takuto. Since the fort. Has it said anything?","mono":false,"off":392.9753,"dur":2.603,"env":"0169821398233899986423576320621137876520110001464541335873435676400333320000000"},"ep07_122":{"who":"TAKUTO","text":"Last night. During the fight. It said let me look.","mono":false,"off":395.978,"dur":2.752,"env":"00259874516777542137655553111987532100000000006513448983246423454345410001000000000"},"ep07_123":{"who":"RIN","text":"And?","mono":false,"off":399.13,"dur":0.491,"env":"069999656531000"},"ep07_124":{"who":"TAKUTO","text":"And I said no. And then it said it was curious what I would do. With the ogre.","mono":false,"off":400.0207,"dur":4.587,"env":"000356877544369842456666532110000002566666413359747214340011135666444433201444554423321102455321110000000025200332135665211211000000000000"},"ep07_125":{"who":"RIN","text":"...Thank you for telling me.","mono":false,"off":405.0073,"dur":1.365,"env":"02229986211663117403267655554433322000000"},"ep07_126":{"who":"TAKUTO","text":"You made me promise.","mono":false,"off":406.7727,"dur":1.237,"env":"01355889536640116777653221122210000000"},"ep07_127":{"who":"RIN","text":"I know. Thank you for keeping it. Most people don't.","mono":false,"off":408.41,"dur":2.709,"env":"0679999999887411187731451152021663045544420003578745200145500465227643311120000000"},"ep07_128":{"who":"AKURO","text":"Telling on me to the girl. That is low, boy. I am wounded.","mono":true,"off":411.5193,"dur":3.669,"env":"014448767777779777634345533679996531000013687576554457989998794212576788754322102455555664334886665323221110000"},"ep07_129":{"who":"TAKUTO","text":"It says it is wounded.","mono":false,"off":415.5887,"dur":1.259,"env":"13112289424435321123444432111100000000"},"ep07_130":{"who":"RIN","text":"Good.","mono":false,"off":417.2473,"dur":0.533,"env":"0399998523321000"},"ep07_131":{"who":"CROWD","text":"Where did your boy go, Hunter? To warn his friends?","mono":false,"off":418.1807,"dur":3.051,"env":"02563642586310899976320277654332111255520221110000001343355544433310025443111011222000000000"},"ep07_132":{"who":"HUNTER","text":"Valen. My people want torches and the forest. Tonight.","mono":false,"off":421.6313,"dur":3.584,"env":"001588997665554456640026520354335531011365401123311332220000444433221110000001333333221000000000000000000000"},"ep07_133":{"who":"SIEG","text":"Then your people will die in the forest tonight, Abel. With torches in their hands.","mono":false,"off":425.6153,"dur":4.821,"env":"0887777641018752066666666642675555553246655310066656653202577765653100000057887555433100000000004993003368652243876557676655654686654322222322000"},"ep07_134":{"who":"CROWD2","text":"They burned our barn!","mono":false,"off":430.8367,"dur":1.472,"env":"028995213977766558862178555544322121110000000"},"ep07_135":{"who":"CROWD","text":"They took our grain!","mono":false,"off":432.7087,"dur":1.621,"env":"0157640054496017865321255555543221111100000000000"},"ep07_136":{"who":"SIEG","text":"They took grain. And they could have taken children. Four nights, three raids, and not one of you is dead. Think about that.","mono":false,"off":434.73,"dur":6.891,"env":"089834793000059766676665554000000003998763196751136865216675353676664554332200000000000001987667665555413332101259766667666665654431002788886541047666556666654201876654322000000005995585776530003655421021000"},"ep07_137":{"who":"SIEG","text":"I have fought Fiends for twenty years. The ones that want you dead do not stop at the granary.","mono":false,"off":442.0207,"dur":5.589,"env":"058986311786411110487677666543210563131776537666666543322332000000000000398876666530663047765411178764267665544200000005998765542024330576654005312642687765554332211000"},"ep07_138":{"who":"HUNTER","text":"And if you are wrong?","mono":false,"off":448.01,"dur":1.429,"env":"0003678910148988987653336665432111110000000"},"ep07_139":{"who":"SIEG","text":"Then I will stand at your gate myself, with both swords, and I will not move until it is morning.","mono":false,"off":449.8393,"dur":5.973,"env":"039866656556544330576665655521277532876410067665333276643211000000000597410876651233368765554433310000000000178877776787655530069867666654100000587333976764576544887766544321110000"},"ep07_140":{"who":"SIEG","text":"Go home. Lock your doors. Let the boy do something nobody has tried before.","mono":false,"off":456.2127,"dur":4.715,"env":"0998888798767766541000049863015986429877654323432000000000087219864865666655874428653147777776665556544666568541245866675312641116765432110000"},"ep07_141":{"who":"NEMU","text":"There are small ones. Look. Children.","mono":false,"off":461.3273,"dur":2.496,"env":"002556534341787666422232211222000000000000005996101000024316644132322100000"},"ep07_142":{"who":"WICK","text":"There must be fifty of them. All hiding.","mono":false,"off":464.2233,"dur":1.899,"env":"056764116511196112477423545531026777532475442321111000000"},"ep07_143":{"who":"OGRE","text":"White one. You followed.","mono":false,"off":466.522,"dur":1.899,"env":"013678831034555432210000000000137962224775666768543321000"},"ep07_144":{"who":"TAKUTO","text":"You said the grey is coming. I want to know what it is.","mono":false,"off":468.8207,"dur":2.944,"env":"01334339941261126665444332012664311110000000003565468644455554433443323543210012110000000"},"ep07_145":{"who":"OGRE","text":"Wolves. A grey pack. Hundreds. Red eyes. They do not eat. They only chase.","mono":false,"off":472.1647,"dur":5.44,"env":"02476776544312111112221124567543320012443321000000000000158776633433211111000137897433455656544211112210000013425654464541013432210000001344565433421233454432111100"},"ep07_146":{"who":"OGRE","text":"They chase us from the deep wood. Out to the roads. Out to your farms. Out to your swords.","mono":false,"off":478.0047,"dur":6.187,"env":"012796311233356564334554221465744321365441002334668763111100000000147887311464477555778984421100111100000000135787420123476421158665654322223211000000137896410124456533235665676431101100"},"ep07_147":{"who":"RIN","text":"They are pushing you at the villages. On purpose.","mono":false,"off":484.5913,"dur":2.475,"env":"037893011794445788777810542686773124544322210002677631147850034211221000000"},"ep07_148":{"who":"OGRE","text":"At the head of the pack walks a wolf with a man's back. With a long blade. He laughs when we run.","mono":false,"off":487.466,"dur":6.507,"env":"0186123432247876564324310112464442000014576323455433356553112355566775555555543211477543210000000000000003595677654566995545663235566567742211000000000000012455568776531233225566444447896432110000"},"ep07_149":{"who":"OGRE","text":"And beside him, sometimes, a thing in a black skin. It crackles. Like lightning in a jar.","mono":false,"off":494.3727,"dur":6.336,"env":"01689555333345557995355532221259764113445445332210024431001475532344575313556542012333212467642210000000000000003652001245676520133211101110000014764212434579641134432467434322556567742110000"},"ep07_150":{"who":"TAKUTO","text":"Static.","mono":false,"off":501.1087,"dur":0.747,"env":"01210999876552000000000"},"ep07_151":{"who":"RIN","text":"He is herding them. The giants. The Hydra. The ogres. All of them.","mono":false,"off":502.2553,"dur":3.52,"env":"0047994421278957787665555310362247877776642033310353257772257642045236785115543330055666310042221000000000"},"ep07_152":{"who":"WICK","text":"Herding them where?","mono":false,"off":506.1753,"dur":1.024,"env":"0019985866676665675543211210000"},"ep07_153":{"who":"OGRE","text":"West. Always west. Toward the golden city.","mono":false,"off":507.5993,"dur":3.349,"env":"02589775322221000000035787537779532234697542111110000000000000243456894453246767445543224544343211000"},"ep07_154":{"who":"NEMU","text":"Saint Lumen.","mono":false,"off":511.3487,"dur":0.875,"env":"012228851059986543221110000"},"ep07_155":{"who":"TAKUTO","text":"Why can you talk? Everyone says Fiends can't talk.","mono":false,"off":512.6233,"dur":3.072,"env":"003577115565313226999421000000000577246645554232654331004444442201254421021255420000000000000"},"ep07_156":{"who":"OGRE","text":"Everyone says. Nobody asks. My grandmother's grandmother came from the Rift. We stayed. We learned. We are not all teeth, white one.","mono":false,"off":516.0953,"dur":8.811,"env":"0168436654654431222365434321110012467653356544322245532101111011111000000000000000002333311256775434562466421013577644444223320124444212344342124666210000000001445344321246666443211000124754344997643443210000001355665565456643200113432321000000124675430013221100000"},"ep07_157":{"who":"OGRE","text":"You. You have something in your axe that is all teeth. I can smell it.","mono":false,"off":525.306,"dur":4.459,"env":"01347667532100024433689522368621354455555575332568663112221344354335586553100121355322100000000000000000267721456332333236787654200000"},"ep07_158":{"who":"AKURO","text":"Rude. Accurate, but rude.","mono":true,"off":530.1647,"dur":1.792,"env":"003449697665321257763112455553114642244666621211111000"},"ep07_159":{"who":"TAKUTO","text":"I know. I keep the door shut.","mono":false,"off":532.3567,"dur":1.707,"env":"0257778999997524662126102524656535455763100000000000"},"ep07_160":{"who":"OGRE","text":"Good. Keep it shut. The grey likes open doors.","mono":false,"off":534.4633,"dur":3.776,"env":"013474697531110001255642342122223696542000000000000000000134311354566445565412210136753123423234545554322111111000"},"ep07_161":{"who":"WICK","text":"Hey. Hey, little guys. Want to see a trick?","mono":false,"off":538.6393,"dur":2.027,"env":"0677765589997597963399986555331468765444366512247320000000000"},"ep07_162":{"who":"WICK","text":"Three blue fireballs. Watch. Watch!","mono":false,"off":541.066,"dur":2.005,"env":"0158984379961168666663265544332357665411211135643210121000000"},"ep07_163":{"who":"CROWD2","text":"Ha ha ha!","mono":false,"off":543.4713,"dur":1.173,"env":"023489998424777522566544322100000000"},"ep07_164":{"who":"OGRE","text":"They have not laughed since the grey came. Thank you, fire head.","mono":false,"off":545.0447,"dur":4.181,"env":"012676555433475665311244676553211123465222332136567542014665542101000000000000000014697642013534220000156666686434675553110000"},"ep07_165":{"who":"WICK","text":"Fire head. I like that. Nobody has ever called me that with respect.","mono":false,"off":549.626,"dur":3.691,"env":"009977887568887341578767776210175443101000003799953996878965327637611228877347653553234113355205632100020000000"},"ep07_166":{"who":"NEMU","text":"Eyes. In the trees. So many eyes.","mono":false,"off":553.7167,"dur":2.475,"env":"056776543212104975504312653100012100000000000112398886653046532210000221000"},"ep07_167":{"who":"OGRE","text":"The grey! The grey is here! Little ones, RUN!","mono":false,"off":556.5913,"dur":3.328,"env":"0174101236797655433100000133211344755633454332124474210000000000000135675677444553422123698553211000"},"ep07_168":{"who":"WICK","text":"Get behind the fire! Only the wolves burn! Only the wolves!","mono":false,"off":560.3193,"dur":3.008,"env":"0482056357665631179865554300046666676474356652331017655443310146566552543443221003332000000"},"ep07_169":{"who":"RIN","text":"Left! Three of them!","mono":false,"off":563.7273,"dur":1.131,"env":"0599731031025799993236445432000000"},"ep07_170":{"who":"TAKUTO","text":"Break!","mono":false,"off":565.258,"dur":0.64,"env":"00489976520011100000"},"ep07_171":{"who":"AKURO","text":"So many, boy. Hundreds. You will never stop them with one axe and two hands. Let me help.","mono":true,"off":566.298,"dur":6.677,"env":"002335975435677654554211366767666544321112356755433445332111211000000124657567755665344533333125666853001346443432112345665521134554431001222234312223334421134333332211111100124433122321124433210000000"},"ep07_172":{"who":"TAKUTO","text":"Rin. It's talking. Now.","mono":false,"off":573.3753,"dur":1.536,"env":"01378875422521430249940133333444553211000000000"},"ep07_173":{"who":"RIN","text":"Then hold still. Red Thread. Wrist to wrist.","mono":false,"off":575.3113,"dur":2.347,"env":"04786489985133227876653379883000148765521100268433023543664311222010000"},"ep07_174":{"who":"RIN","text":"If you go red, I feel it. And I pull.","mono":false,"off":578.058,"dur":2.219,"env":"0321364159887437766513345411125554432022000454555400004443211000000"},"ep07_175":{"who":"TAKUTO","text":"Then don't let go.","mono":false,"off":580.6767,"dur":1.237,"env":"00178888697424773000488763221110000000"},"ep07_176":{"who":"TAKUTO","text":"Behind the ogres! Nemu, the children!","mono":false,"off":582.314,"dur":2.496,"env":"054348876454337996123321112210000034676666565553142054355431122100000000000"},"ep07_177":{"who":"NEMU","text":"Got them!","mono":false,"off":585.21,"dur":0.875,"env":"034976531002655442100000000"},"ep07_178":{"who":"WICK","text":"Fire head coming through! Little ones, behind me!","mono":false,"off":586.4847,"dur":2.475,"env":"006986667534784202475655202146654310014757645655552053112555443221101000000"},"ep07_179":{"who":"NEMU","text":"Two of the children ran the wrong way! Into the trees!","mono":false,"off":589.3593,"dur":3.861,"env":"02316867411612532654221342210000477765553355555443334322110000000000000000000000000019951524024033215542100001322000"},"ep07_180":{"who":"TAKUTO","text":"Go. I have the front.","mono":false,"off":593.6207,"dur":1.323,"env":"0058999873146656642141111554211011000000"},"ep07_181":{"who":"NEMU","text":"Don't go red while I'm gone.","mono":false,"off":595.3433,"dur":1.749,"env":"04379510449852287542130000000375678765236532111000000"},"ep07_182":{"who":"RIN","text":"Takuto, they are trying to split us!","mono":false,"off":597.4927,"dur":2.027,"env":"0169950169822269998764578773121666662433201585253212221000000"},"ep07_183":{"who":"TAKUTO","text":"Let them try!","mono":false,"off":599.9193,"dur":1.045,"env":"00389208674342898764321110000000"},"ep07_184":{"who":"NEMU","text":"Got them! Both of them! One bit me!","mono":false,"off":601.3647,"dur":2.645,"env":"03675431002477630004788633225121132221000000000000000002799886474005875321100000"},"ep07_185":{"who":"OGRE","text":"White one! Together!","mono":false,"off":604.41,"dur":1.664,"env":"02589974222687875422100000000358842368886577431000"},"ep07_186":{"who":"TAKUTO","text":"Together!","mono":false,"off":606.474,"dur":0.725,"env":"0224229994454331100000"},"ep07_187":{"who":"TAKUTO","text":"Ruinbreaker!","mono":false,"off":607.5993,"dur":0.981,"env":"013688877647986202553210000000"},"ep07_188":{"who":"KUROZANE","text":"Ha. The little F-rank who talks to monsters.","mono":false,"off":608.9807,"dur":3.051,"env":"00126999998765226546758741564000465544200341013554200110144443334311100221110010000000000000"},"ep07_189":{"who":"KUROZANE","text":"Tell the Laughing Blade. Kurozane remembers Grey Hollow.","mono":false,"off":612.4313,"dur":3.84,"env":"01169872485689984002444303456554322110000001167765323544443333444433233321000244444332112443321111000000000000000000"},"ep07_190":{"who":"WICK","text":"Was that... was that a wolf? Standing up? With a sword?","mono":false,"off":616.6713,"dur":2.517,"env":"0664229977511247631786775458765201220566666666620015414443336543322000000000"},"ep07_191":{"who":"RIN","text":"Kurozane. The Fang Ronin. There are posters for him in every Guild hall. Rank A bounty.","mono":false,"off":619.5887,"dur":5.013,"env":"0117999964486677763044111876776567666554333200007888820114775242255443115422555543552015631365103765511005654321000000015655313304544443031211000000000"},"ep07_192":{"who":"TAKUTO","text":"Grey Hollow. That is where Sieg lost his squad.","mono":false,"off":625.002,"dur":2.752,"env":"00488987643578995543211000000686843255443324542134555532013333101565321100000000000"},"ep07_193":{"who":"RIN","text":"...You held on. The thread never pulled. Not once.","mono":false,"off":628.154,"dur":2.475,"env":"036763467762877666654152011597721677742640103654431103555401344332113331000"},"ep07_194":{"who":"TAKUTO","text":"I could feel you on the other end. It was enough.","mono":false,"off":631.0287,"dur":2.752,"env":"04530249211113579753234444444444552544445431111000000000452244444545642100000000000"},"ep07_195":{"who":"OGRE","text":"We go north. Away from the gold city. Away from the grey.","mono":false,"off":634.1807,"dur":4.373,"env":"026832687664344355687432100000000000036542478854332144543532256876422234447742311000000000000013664456656552233445421456976542100000"},"ep07_196":{"who":"TAKUTO","text":"The village will give you grain for the road. Sieg paid for it. Wick paid too.","mono":false,"off":638.954,"dur":4.352,"env":"04222896566313113421144112311135443343211222322345432110000000012324431001234444111022222110000000343000123333200321442100000000000"},"ep07_197":{"who":"WICK","text":"All my reward money. Every coin. I am a broke Hunter now. Please clap.","mono":false,"off":643.706,"dur":3.819,"env":"0488679785698447997357756653100397237721217765432210015677787521899840228634455555433220021455547312366421000000000"},"ep07_198":{"who":"NEMU","text":"I will clap later. I am tired.","mono":false,"off":647.9247,"dur":2.261,"env":"01585620311775302035443222100000000000003898764061225565421100002000"},"ep07_199":{"who":"OGRE","text":"Take this, white one. A feather from my mother. If you meet my people, show it. They will not fight you.","mono":false,"off":650.586,"dur":6.485,"env":"023788320001358642222211123578542112331111000000000135321146784565225744456545546642221000000000002442246544532101455541002443113322211222369776432000000000135754385434466653100136553211122110000"},"ep07_200":{"who":"TAKUTO","text":"...Thank you.","mono":false,"off":657.4713,"dur":0.853,"env":"00019976401256553211000000"},"ep07_201":{"who":"OGRE","text":"And you, thread girl. You held him. I saw. That is a strong thread.","mono":false,"off":658.7247,"dur":4.48,"env":"016787446644321000248875211466543211000000268753378774235431100000014776644433577888441000000246734554564432135887654531012499752100000"},"ep07_202":{"who":"RIN","text":"It is my brother's.","mono":false,"off":663.6047,"dur":1.195,"env":"058947974289878511787515433222210000"},"ep07_203":{"who":"OGRE","text":"Then he is strong too. Still.","mono":false,"off":665.1993,"dur":2.261,"env":"01377588874753331149999564211235745653111000000000123214779986321100"},"ep07_204":{"who":"OGRE","text":"Do not go to the gold city, white one. The gold city is where the grey is going.","mono":false,"off":667.8607,"dur":5.739,"env":"00147556666521002557642243432136787532123334554332210000000002468743100133321111000000000000000000143212679854422233467434323332213587533311235766573444421146796653321100000"},"ep07_205":{"who":"NEMU","text":"We are going to the gold city.","mono":false,"off":673.9993,"dur":1.685,"env":"002576204899976420005105404665433202333344111100000"},"ep07_206":{"who":"TAKUTO","text":"I know.","mono":false,"off":676.0847,"dur":0.747,"env":"03677778999854210000000"},"ep07_207":{"who":"OGRE","text":"White one. Before we go. The thing in your axe. Do you know its name?","mono":false,"off":677.2313,"dur":4.373,"env":"013699941124666553321244322777755521267879843110000000134422667766576567542478753200023332100000001334356658876312325567865433110000"},"ep07_208":{"who":"TAKUTO","text":"Akuro. The Crimson Calamity.","mono":false,"off":682.0047,"dur":2.005,"env":"1563011575498986432113002555434334321134344443211110000000000"},"ep07_209":{"who":"OGRE","text":"My people have a song about the red one. The one who broke the sky.","mono":false,"off":684.41,"dur":4.629,"env":"0245556411243311244324753443333334566665434343367311344345974221233211110000000000000000003354656656324211376983000233332124455555322110000"},"ep07_210":{"who":"TAKUTO","text":"Broke the sky?","mono":false,"off":689.4393,"dur":1.045,"env":"00499920054430597755322111000000"},"ep07_211":{"who":"OGRE","text":"Three hundred winters ago, there were no Rifts. Then the red one fought something in the clouds, and the sky cracked.","mono":false,"off":690.8847,"dur":7.445,"env":"00124544544465546643225853324444322311344654532000001367985654456544443356441000001121100000000000000000124778735665358873334765632013388421124752213444444332011135568765333221111100002554434443134446545320012476542100000000"},"ep07_212":{"who":"OGRE","text":"The cracks never healed. That is what the song says. Every Rift is a scar from that fight.","mono":false,"off":698.73,"dur":6.357,"env":"01831112368764410122213245785458732245465753211000000000000000247863235532376411333322367777445432234553221111000000000013697554455446766510012343444333321356679885324644576420002555543100000"},"ep07_213":{"who":"AKURO","text":"...Songs. Ogres and their songs. They always get the order of things wrong.","mono":true,"off":705.4873,"dur":5.056,"env":"00122234799787777765221014688897323456543221246646764333356755643211111110000127752257788654586642126621342114678665666410023555554221245654433210100000"},"ep07_214":{"who":"TAKUTO","text":"It says your song gets the order wrong.","mono":false,"off":710.9433,"dur":2.069,"env":"031022996223423226656443321552010033344324323443210000000000000"},"ep07_215":{"who":"OGRE","text":"Ha. Then ask it what the right order is. And listen carefully, when it lies.","mono":false,"off":713.4127,"dur":5.376,"env":"003699787642100000014899853235675343124431034551257543577653003557645765545332101111000000000000134675557544465452101248663123233321122676542135455455643211111000"},"ep07_216":{"who":"TAKUTO","text":"Akuro. What did you fight in the sky?","mono":false,"off":719.1887,"dur":2.368,"env":"148840122997599876431000136514324431117765534444344314554311010000000000"},"ep07_217":{"who":"AKURO","text":"...Something that wears a suit now. Go away, boy. I am tired.","mono":true,"off":721.9567,"dur":4.288,"env":"002347966226556757864225686753233443433333223444332111000000013799689645787665412557866654320144555445652122223455543322111000000"},"ep07_218":{"who":"RIN","text":"Nemu. At the fort. You were the one who shouted.","mono":false,"off":726.6447,"dur":2.56,"env":"03788999999987437202412137776520131000365682774576545534435554422321110000000"},"ep07_219":{"who":"NEMU","text":"Mm.","mono":false,"off":729.6047,"dur":0.875,"env":"005589999997755421100000000"},"ep07_220":{"who":"RIN","text":"I shouted too. He did not hear me. He heard you.","mono":false,"off":730.8793,"dur":2.603,"env":"0685454799985951044188766531066384588861115786665543103542578851234321100000000"},"ep07_221":{"who":"NEMU","text":"He did not hear you because you were flying. It is hard to hear someone who is flying.","mono":false,"off":733.882,"dur":5.995,"env":"000725870069975411014665323443110000000000241347432463342111244432100000000000000000000000000000000000692754311127888762014431137654423466544343210000000676554211044444321010000000"},"ep07_222":{"who":"RIN","text":"...Is that a joke?","mono":false,"off":740.2767,"dur":1.067,"env":"04995419987852348876541011000000"},"ep07_223":{"who":"NEMU","text":"Half a joke. The other half is true. You were very high up.","mono":false,"off":741.7433,"dur":4.053,"env":"00178511622545664200001000000000000000000011326962875224566300034530421566421000000000007657412765444211345543222210001000"},"ep07_224":{"who":"RIN","text":"Thank you. For bringing him back.","mono":false,"off":746.1967,"dur":1.621,"env":"0299883224676522257313986766566643754321001000000"},"ep07_225":{"who":"NEMU","text":"You are tying him down now. With your thread. That is better than shouting. Shouting is tiring.","mono":false,"off":748.218,"dur":6.827,"env":"0011640432289998764866347766655444322111100000000000000005512586211216653211110000000000000000000000266623645002777514433015554544254443221100000000000000000002343888876636654220075430411245543211110000000"},"ep07_226":{"who":"RIN","text":"Then we take turns.","mono":false,"off":755.4447,"dur":1.237,"env":"05988997132787500023665544332222100000"},"ep07_227":{"who":"NEMU","text":"Mm. Deal. You go first. I am going to sleep.","mono":false,"off":757.082,"dur":3.627,"env":"0268889987654200004586654221000000001850599732111533211244303000000000000001489878459787525354441244210001100"},"ep07_228":{"who":"TAKUTO","text":"Sieg. There was a wolf in the forest. Standing on two legs. With a sword.","mono":false,"off":761.1087,"dur":4.331,"env":"0022266665311486553664337986111344441100366774211022000000000021196766655566541241455435777532111210231333333465542210000000000000"},"ep07_229":{"who":"TAKUTO","text":"He said to tell you. Kurozane remembers Grey Hollow.","mono":false,"off":765.8393,"dur":3.456,"env":"00233329841122032577643221000000000000114788753365454434444544432433220003444443311456652122100000000000"},"ep07_230":{"who":"SIEG","text":"...So he is still alive.","mono":false,"off":769.6953,"dur":1.536,"env":"02399899986766322107976776777766665554321000000"},"ep07_231":{"who":"TAKUTO","text":"Who is he?","mono":false,"off":771.6313,"dur":0.896,"env":"000798995431476432110000000"},"ep07_232":{"who":"SIEG","text":"The night before Morvudd came, he walked into our camp. Behind the man in the black suit. He was the one who cut the alarm ropes.","mono":false,"off":772.9273,"dur":7.787,"env":"059986652000762167767776665465542013976666655200000007988876542002776367665112687643100000000000000187558766666566666655555541001787653176654015433498531121000000000000199986487676555676974101384100058776666655555556666543210034332000"},"ep07_233":{"who":"SIEG","text":"I cut out his left eye. He took the last of my squad while I was doing it.","mono":false,"off":781.114,"dur":4.48,"env":"058512396457556578653776551102655654444310000000000873496200066666554543116566545533200665555555420000366656655654103876654432210110000"},"ep07_234":{"who":"TAKUTO","text":"He wants you.","mono":false,"off":785.994,"dur":1.003,"env":"0025536999852233134421110000000"},"ep07_235":{"who":"SIEG","text":"He always did. A duel. The Laughing Blade against the Fang Ronin. He thinks it is a song.","mono":false,"off":787.3967,"dur":5.675,"env":"049556765565664102766554320000000487527976665433320000000000888776542146666642765656556437753420363103866566666655554443332000000000197267743337657654654333586543221100000"},"ep07_236":{"who":"TAKUTO","text":"Is it?","mono":false,"off":793.4713,"dur":0.619,"env":"0156438985200000000"},"ep07_237":{"who":"SIEG","text":"...Ask me tomorrow, Takuto. Tonight I want to sit here and count the stars. All of them. Twice.","mono":false,"off":794.49,"dur":5.973,"env":"047654305975228776555566555530267641078732586555520000000006997655414556665431264322674112776545564116865311543303755554443333200000000005877776445655554200000002189654332232221000"},"ep07_238":{"who":"HUNTER","text":"The ogres are gone north. No blood on our fields. I was wrong about you, boy.","mono":false,"off":800.8633,"dur":4.693,"env":"001335798423763244211544433444433322100002333421024554233222200002222211100011000000222211124443332122311001210023222111000000000000000000000"},"ep07_239":{"who":"HUNTER","text":"I do not say that often. Do not make me say it twice.","mono":false,"off":805.9567,"dur":3.627,"env":"0035366899510224987643655345554100132222100344555423442003431113554333100001025432221000000000000000000000000"},"ep07_240":{"who":"CROWD2","text":"Mister white hair! This is for you. My mum baked it. It is only a little burnt.","mono":false,"off":809.9833,"dur":3.925,"env":"0498423785599863112455554213423233331034334433210137764448855415643002343200000054853765444454243541046444210220000000"},"ep07_241":{"who":"TAKUTO","text":"...Thank you.","mono":false,"off":814.3087,"dur":0.853,"env":"00019976401256553211000000"},"ep07_242":{"who":"WICK","text":"Only a little burnt. That is the highest praise in this world. Trust me.","mono":false,"off":815.562,"dur":3.477,"env":"057777787885786842398775411014787575348322389656654100147666643455544203444432110001176342023111100000000"},"ep07_243":{"who":"NEMU","text":"Can I have half?","mono":false,"off":819.4393,"dur":1.067,"env":"02198978832478211145331100111000"},"ep07_244":{"who":"TAKUTO","text":"You can have half.","mono":false,"off":820.906,"dur":1.109,"env":"0144128956567731235542110000000000"},"ep07_245":{"who":"NEMU","text":"Can I have the bigger half?","mono":false,"off":822.4153,"dur":1.536,"env":"02178988996112799210271398126532243311001110000"},"ep07_246":{"who":"SIEG","text":"Come on. The pass is two days up the mountain. And then the capital.","mono":false,"off":824.3513,"dur":4.309,"env":"0278665555555554433463014765555332156530032866546665665563003666654556642154332100000000017997766655400000065112486530053332210000"},"ep07_247":{"who":"KUROZANE","text":"You want me to kill the boy who talks to monsters?","mono":false,"off":829.0607,"dur":3.157,"env":"01355478953566341011776423521046766655432232011355410110013333333321110121111000000000000000000"},"ep07_248":{"who":"SABLE","text":"No, no. Kill the teacher. The boy will follow him anywhere. Even into the ground.","mono":false,"off":832.618,"dur":5.099,"env":"002168996668877644322001133211237622125852111000000001211458863333122124444331122212333321211110000000012453243444551121124333221111110000000000000000000"},"ep07_249":{"who":"KUROZANE","text":"Valen. Finally. I have waited six years for that laugh to stop.","mono":false,"off":838.1167,"dur":4.352,"env":"00117899855655431000365444432221111000000134445312356553441012215200110234433211002213431012344320000111101433221000000000000000000"},"ep07_250":{"who":"TAKUTO","text":"Next time: the old shrine on the mountain pass.","mono":false,"off":842.8687,"dur":2.731,"env":"0147820430287776432211342269873134215655554444444444444421233202344210001111000000"},"ep07_251":{"who":"TAKUTO","text":"Kurozane challenges Sieg to a duel. Sieg says yes.","mono":false,"off":845.9993,"dur":3.499,"env":"001799983496665324178765554234322213443210224442136664432110000000000124764212226553212465311011100000000"},"ep07_252":{"who":"TAKUTO","text":"Afterimage against the wolf's blade. Six years of waiting, in one cut.","mono":false,"off":849.898,"dur":4.416,"env":"0068971016766762345214654231053346651121002467654311100000000000002337810331245666533522256655433322102344444444301147620000000000000"},"ep07_253":{"who":"TAKUTO","text":"Episode eight. The Fang Ronin.","mono":false,"off":854.714,"dur":2.069,"env":"046115444698743236753100000004311186655544455565432110000000000"}}};
